import fs from 'fs';
import path from 'path';
import { Plugin, PluginContext, SSGConfig } from './plugin';
import { BuildOptions, Page } from './types';
import { MarkdownPlugin } from '../plugins/markdown';
import { TemplatePlugin } from '../plugins/template';

const DEFAULT_CONTENT_DIR = 'content';
const DEFAULT_OUTPUT_DIR = 'dist';
const DEFAULT_TEMPLATE_DIR = 'templates';

export function collectMarkdownFiles(dir: string): string[] {
  const results: string[] = [];
  if (!fs.existsSync(dir)) {
    return results;
  }
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  entries.sort((a, b) => a.name.localeCompare(b.name));
  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      results.push(...collectMarkdownFiles(fullPath));
    } else if (entry.isFile() && entry.name.toLowerCase().endsWith('.md')) {
      results.push(fullPath);
    }
  }
  return results;
}

export function toSlug(sourcePath: string, baseDir?: string): string {
  let relative = baseDir ? path.relative(baseDir, sourcePath) : path.basename(sourcePath);
  relative = relative.replace(/\\/g, '/');
  const parsed = path.parse(relative);
  const base = parsed.name === 'index' ? '' : parsed.name;
  const dir = parsed.dir ? `${parsed.dir}/` : '';
  return `${dir}${base}`.replace(/\/+$/, '') || 'index';
}

/**
 * The core SSG engine. It loads plugins (built-in plus any configured through
 * ssg.config.ts) and orchestrates the plugin pipeline.
 */
export class SSGEngine {
  readonly config: SSGConfig;
  private readonly plugins: Plugin[];

  constructor(config: SSGConfig = {}) {
    this.config = config;
    this.plugins = buildPluginList(config);
  }

  get pluginList(): Plugin[] {
    return [...this.plugins];
  }

  addPlugin(plugin: Plugin): void {
    if (!this.plugins.some((p) => p.name === plugin.name)) {
      this.plugins.push(plugin);
    }
  }

  private createContext(options: BuildOptions): PluginContext {
    return {
      options,
      contentDir: path.resolve(options.contentDir ?? DEFAULT_CONTENT_DIR),
      outputDir: path.resolve(options.outputDir ?? DEFAULT_OUTPUT_DIR),
      templateDir: path.resolve(options.templateDir ?? DEFAULT_TEMPLATE_DIR),
      pages: [],
      config: this.config,
    };
  }

  private runHook(hook: 'onStart' | 'beforeBuild' | 'afterBuild' | 'onEnd', ctx: PluginContext): void {
    for (const plugin of this.plugins) {
      const fn = plugin[hook];
      if (fn) {
        fn.call(plugin, ctx);
      }
    }
  }

  private runOnFile(page: Page, ctx: PluginContext): Page {
    let current = page;
    for (const plugin of this.plugins) {
      if (plugin.onFile) {
        const result = plugin.onFile(current, ctx);
        if (result) {
          current = result;
        }
      }
    }
    return current;
  }

  /**
   * Per-build pipeline: beforeBuild -> onFile (per page) -> afterBuild.
   * Used both by build() and by live-reload rebuilds.
   */
  buildOnce(options: BuildOptions = {}): Page[] {
    const ctx = this.createContext(options);
    this.runHook('beforeBuild', ctx);

    const files = collectMarkdownFiles(ctx.contentDir);
    const pages = files.map((file) =>
      this.runOnFile({ sourcePath: file, slug: toSlug(file, ctx.contentDir) } as Page, ctx)
    );
    ctx.pages = pages;

    this.runHook('afterBuild', ctx);
    return pages;
  }

  /**
   * Full lifecycle run: onStart -> buildOnce -> onEnd.
   */
  build(options: BuildOptions = {}): Page[] {
    const ctx = this.createContext(options);
    this.runHook('onStart', ctx);
    const pages = this.buildOnce(options);
    this.runHook('onEnd', ctx);
    return pages;
  }

  /**
   * Starts the pipeline up to the first build. Lifecycle onEnd is deferred
   * until stop() so that long-running plugins (e.g. the dev server) survive
   * repeated rebuilds.
   */
  start(options: BuildOptions = {}): Page[] {
    const ctx = this.createContext(options);
    this.runHook('onStart', ctx);
    return this.buildOnce(options);
  }

  stop(): void {
    const ctx = this.createContext({});
    this.runHook('onEnd', ctx);
  }
}

function buildPluginList(config: SSGConfig): Plugin[] {
  const list: Plugin[] = [];
  const names = new Set<string>();
  const push = (plugin: Plugin): void => {
    if (!names.has(plugin.name)) {
      names.add(plugin.name);
      list.push(plugin);
    }
  };

  push(new MarkdownPlugin());
  push(new TemplatePlugin());

  for (const plugin of config.plugins ?? []) {
    push(plugin);
  }
  return list;
}

import fs from 'fs';
import path from 'path';
import { SSGConfig } from './plugin';

const DEFAULT_CONFIG_FILE = 'ssg.config.ts';
const COMPILED_CONFIG_FILE = 'ssg.config.js';

export function findConfigFile(configPath?: string): string | undefined {
  const candidates: string[] = [];
  if (configPath) {
    candidates.push(path.resolve(configPath));
  }
  candidates.push(path.resolve(DEFAULT_CONFIG_FILE));
  candidates.push(path.resolve(COMPILED_CONFIG_FILE));
  for (const candidate of candidates) {
    if (fs.existsSync(candidate)) {
      return candidate;
    }
  }
  return undefined;
}

export function loadConfig(configPath?: string): SSGConfig {
  const file = findConfigFile(configPath);
  if (!file) {
    return {};
  }
  // eslint-disable-next-line @typescript-eslint/no-var-requires
  const mod = require(file);
  const config = (mod && mod.default) ?? mod;
  if (config && typeof config === 'object') {
    return config as SSGConfig;
  }
  return {};
}

import { Plugin, PluginContext } from '../src/plugin';
import { Page } from '../src/types';
import { parseMarkdownFile } from '../src/parser';

/**
 * Built-in plugin responsible for reading Markdown source files, parsing
 * frontmatter, and rendering Markdown to HTML for every content page.
 */
export class MarkdownPlugin implements Plugin {
  readonly name = 'markdown';

  onFile(page: Page, ctx: PluginContext): Page {
    return parseMarkdownFile(page.sourcePath, ctx.contentDir);
  }
}

import fs from 'fs';
import path from 'path';
import { Plugin, PluginContext } from '../src/plugin';
import { TemplateEngine, renderIndex } from '../src/template';

/**
 * Built-in plugin responsible for rendering every page through the Handlebars
 * template engine and writing the generated HTML files (including the index)
 * into the output directory.
 */
export class TemplatePlugin implements Plugin {
  readonly name = 'template';
  private engine: TemplateEngine | undefined;

  beforeBuild(ctx: PluginContext): void {
    this.engine = new TemplateEngine({
      templateDir: ctx.templateDir,
      defaultTemplate: ctx.options.defaultTemplate,
      defaultLayout: ctx.options.defaultLayout,
    });
    fs.rmSync(ctx.outputDir, { recursive: true, force: true });
    fs.mkdirSync(ctx.outputDir, { recursive: true });
  }

  afterBuild(ctx: PluginContext): void {
    const engine = this.engine ?? new TemplateEngine({ templateDir: ctx.templateDir });
    for (const page of ctx.pages) {
      page.rendered = engine.renderPage(page);
      const filePath = path.join(ctx.outputDir, `${page.slug}.html`);
      fs.mkdirSync(path.dirname(filePath), { recursive: true });
      fs.writeFileSync(filePath, page.rendered, 'utf8');
    }
    fs.writeFileSync(path.join(ctx.outputDir, 'index.html'), renderIndex(ctx.pages), 'utf8');
  }
}

export const DEFAULT_SERVE_PORT = 3000;
export const LIVE_RELOAD_PATH = '/__live_reload';

export const MIME_TYPES: Record<string, string> = {
  '.html': 'text/html',
  '.htm': 'text/html',
  '.css': 'text/css',
  '.js': 'application/javascript',
  '.mjs': 'application/javascript',
  '.json': 'application/json',
  '.map': 'application/json',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.svg': 'image/svg+xml',
  '.webp': 'image/webp',
  '.ico': 'image/x-icon',
  '.txt': 'text/plain',
  '.xml': 'application/xml',
  '.woff': 'font/woff',
  '.woff2': 'font/woff2',
  '.ttf': 'font/ttf',
  '.otf': 'font/otf',
  '.pdf': 'application/pdf',
  '.md': 'text/markdown',
};

function liveReloadScript(): string {
  return `\n<script>
(function () {
  var ws;
  var retries = 0;
  function connect() {
    ws = new WebSocket('ws://' + location.host + '${LIVE_RELOAD_PATH}');
    ws.onmessage = function (event) {
      if (event.data === 'reload') {
        location.reload();
      }
    };
    ws.onclose = function () {
      if (retries < 60) {
        retries += 1;
        setTimeout(connect, 500);
      }
    };
    ws.onopen = function () {
      retries = 0;
    };
  }
  connect();
})();
</script>`;
}

export function injectLiveReload(html: string): string {
  const script = liveReloadScript();
  if (/<\/body>/i.test(html)) {
    return html.replace(/<\/body>/i, `${script}\n</body>`);
  }
  if (/<\/html>/i.test(html)) {
    return html.replace(/<\/html>/i, `${script}\n</html>`);
  }
  return html + script;
}

import fs from 'fs';
import http from 'http';
import path from 'path';
import { AddressInfo } from 'net';
import { WebSocket, WebSocketServer } from 'ws';
import chokidar, { FSWatcher } from 'chokidar';
import { Plugin, PluginContext } from '../src/plugin';
import type { SSGEngine } from '../src/engine';
import type { ServeOptions, DevServer } from '../src/serve';
import { DEFAULT_SERVE_PORT, LIVE_RELOAD_PATH, injectLiveReload, MIME_TYPES } from '../src/serve-helpers';

/**
 * Built-in plugin implementing the development server: static file serving of
 * the output directory with WebSocket-based live reload and a file watcher
 * that triggers rebuilds when content or templates change.
 */
export class DevServerPlugin implements Plugin {
  readonly name = 'dev-server';

  private readonly options: ServeOptions;
  private engine: SSGEngine | undefined;
  private server: http.Server | undefined;
  private wss: WebSocketServer | undefined;
  private watcher: FSWatcher | undefined;
  private rebuildTimer: ReturnType<typeof setTimeout> | null = null;
  private boundPort = 0;
  private started = false;
  private rebuilding = false;
  private pending = false;

  constructor(options: ServeOptions) {
    this.options = options;
  }

  attach(engine: SSGEngine): void {
    this.engine = engine;
  }

  onStart(_ctx: PluginContext): void {
    if (this.started) {
      return;
    }
    this.started = true;

    const outputDir = path.resolve(this.options.outputDir ?? 'dist');
    const contentDir = path.resolve(this.options.contentDir ?? 'content');
    const templateDir = path.resolve(this.options.templateDir ?? 'templates');
    const port = this.options.port ?? DEFAULT_SERVE_PORT;
    const host = this.options.host ?? '127.0.0.1';

    const server = http.createServer((req, res) => {
      const requestUrl = new URL(req.url ?? '/', `http://${req.headers.host ?? 'localhost'}`);
      let pathname: string;
      try {
        pathname = decodeURIComponent(requestUrl.pathname);
      } catch {
        res.writeHead(400);
        res.end('Bad Request');
        return;
      }

      let filePath = path.join(outputDir, path.normalize(pathname));
      if (!filePath.startsWith(outputDir + path.sep)) {
        res.writeHead(403);
        res.end('Forbidden');
        return;
      }

      if (fs.existsSync(filePath) && fs.statSync(filePath).isDirectory()) {
        filePath = path.join(filePath, 'index.html');
      } else if (!path.extname(filePath) && fs.existsSync(`${filePath}.html`)) {
        filePath = `${filePath}.html`;
      }

      if (!fs.existsSync(filePath) || fs.statSync(filePath).isDirectory()) {
        res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
        res.end('Not Found');
        return;
      }

      const ext = path.extname(filePath).toLowerCase();
      const mime = MIME_TYPES[ext] ?? 'application/octet-stream';
      let body = fs.readFileSync(filePath);

      if (mime === 'text/html') {
        body = Buffer.from(injectLiveReload(body.toString('utf8')), 'utf8');
      }

      res.writeHead(200, { 'Content-Type': `${mime}; charset=utf-8` });
      res.end(body);
    });

    const wss = new WebSocketServer({ server, path: LIVE_RELOAD_PATH });

    server.listen(port, host);
    server.once('listening', () => {
      const address = server.address() as AddressInfo | null;
      if (address && typeof address === 'object') {
        this.boundPort = address.port;
      }
    });

    const watchPaths = [contentDir, templateDir].filter((dir) => fs.existsSync(dir));
    const watcher = chokidar.watch(watchPaths, { ignoreInitial: false });

    watcher.on('all', (_event, filePath) => {
      if (filePath.startsWith(outputDir + path.sep)) {
        return;
      }
      if (this.rebuildTimer) {
        clearTimeout(this.rebuildTimer);
      }
      this.rebuildTimer = setTimeout(() => {
        this.rebuildTimer = null;
        this.rebuild();
      }, 50);
    });

    this.server = server;
    this.wss = wss;
    this.watcher = watcher;
  }

  private broadcastReload(): void {
    if (!this.wss) {
      return;
    }
    for (const client of this.wss.clients) {
      if (client.readyState === WebSocket.OPEN) {
        client.send('reload');
      }
    }
  }

  rebuild(): void {
    if (!this.engine) {
      return;
    }
    if (this.rebuilding) {
      this.pending = true;
      return;
    }
    this.rebuilding = true;
    try {
      this.engine.buildOnce(this.options);
    } catch (err) {
      console.error('[ssg] rebuild failed:', err instanceof Error ? err.message : err);
    } finally {
      this.rebuilding = false;
      if (this.pending) {
        this.pending = false;
        this.rebuild();
      }
    }
  }

  afterBuild(ctx: PluginContext): void {
    console.log(`[ssg] rebuilt ${ctx.pages.length} page(s)`);
    this.broadcastReload();
  }

  onEnd(): void {
    if (!this.started) {
      return;
    }
    this.started = false;
    if (this.rebuildTimer) {
      clearTimeout(this.rebuildTimer);
      this.rebuildTimer = null;
    }
    if (this.wss) {
      for (const client of this.wss.clients) {
        client.terminate();
      }
      this.wss.close();
      this.wss = undefined;
    }
    if (this.watcher) {
      this.watcher.close();
      this.watcher = undefined;
    }
    if (this.server) {
      this.server.close();
      this.server.closeIdleConnections();
      this.server = undefined;
    }
  }

  get dev(): DevServer {
    return {
      server: this.server as http.Server,
      wss: this.wss as WebSocketServer,
      get port() {
        return this.boundPort;
      },
      watcher: this.watcher as FSWatcher,
      rebuild: () => this.rebuild(),
      close: async () => {
        await this.engine?.stop();
      },
    };
  }
}

import { SSGEngine } from './engine';
import { loadConfig } from './config';
import { Plugin } from './plugin';
import { Page } from './types';

export interface BuildOptions {
  contentDir?: string;
  outputDir?: string;
  templateDir?: string;
  defaultTemplate?: string;
  defaultLayout?: string;
  configPath?: string;
  plugins?: Plugin[];
}

/**
 * Build the static site. Plugins are loaded from ssg.config.ts (or the given
 * configPath); the built-in markdown and template plugins are always included.
 * Returns the parsed pages.
 */
export function build(options: BuildOptions = {}): Page[] {
  const config = options.plugins ? { plugins: options.plugins } : loadConfig(options.configPath);
  const engine = new SSGEngine(config);
  return engine.build(options);
}

